class Solution {
public:
    int makeArrayPositive(vector<int>& nums) {
        int n=nums.size(),ans=0,last=-1;
        for(int r=2;r<n;r++){
            bool bad=false;
            for(int len=3;len<=5 && len<=r+1;len++){
                int l=r-len+1;
                if(l<=last)continue;
                long long sum=0;
                for(int j=l;j<=r;j++)sum+=nums[j];
                if(sum<=0)bad=true;
            }
            if(bad){ans++;last=r;}
        }
        return ans;
    }
};
